"""Copy the LocalKey core into web/py/ so the browser demo runs the same code.

Run from the repo root:  python scripts/build_web.py
"""

from __future__ import annotations

import shutil
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
SRC = ROOT / "src" / "localkey"
DEFAULT_DEST = ROOT / "web" / "py"
CORE_FILES = ("entropy.py", "generators.py")
INIT = (
    '"""Generated by scripts/build_web.py. Do not edit."""\n\n'
    "from .generators import Result, random_password\n\n"
    '__all__ = ["Result", "random_password"]\n'
)


def build(dest: Path = DEFAULT_DEST) -> None:
    package = dest / "localkey"
    package.mkdir(parents=True, exist_ok=True)
    for name in CORE_FILES:
        shutil.copyfile(SRC / name, package / name)
    (package / "__init__.py").write_text(INIT, encoding="utf-8")


def main() -> None:
    build()
    print(f"Copied {', '.join(CORE_FILES)} to {DEFAULT_DEST / 'localkey'}")


if __name__ == "__main__":
    main()
